        continue

    if optional_vars == node:
        if not assign_path:
            yield from _infer_context_manager(self, context_expr, context)
        else:
            for inferred in _infer_context_manager(self, context_expr, context):
                yield from _resolve_assignment_parts(
                    iter([inferred]), assign_path, context
                )

        return {
            "node": self,
            "unknown": node,
            "assign_path": assign_path,
            "context": context,
        }

raise InferenceError(
    "Cannot infer assigned node {node!r} in with statement {self!r}.",
    node=self,
    context=context,
)
return {
